import hashlib
import hmac
import os
import time
import re
from urllib.parse import unquote, urlparse

# Secure session management for API gateway
SECRET_KEY = os.environ.get('API_SECRET', os.urandom(32))
if isinstance(SECRET_KEY, str):
    SECRET_KEY = SECRET_KEY.encode('utf-8')

ACTIVE_SESSIONS = {}
RATE_LIMITS = {}
MAX_REQUEST_SIZE = 1024 * 1024  # 1MB
SESSION_TIMEOUT = 3600

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison to prevent side-channel attacks."""
    return hmac.compare_digest(a, b)

def generate_token(user_id: str, roles: list, ip_addr: str) -> str:
    """Generate a signed session token."""
    timestamp = str(int(time.time()))
    nonce = os.urandom(16).hex()
    payload = f"{user_id}|{','.join(roles)}|{timestamp}|{nonce}|{ip_addr}"
    signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}|{signature}"

def _parse_token_parts(token: str) -> dict:
    """Parse token into component parts."""
    parts = token.split('|')
    if len(parts) != 6:
        return None
    return {
        'user_id': parts[0],
        'roles': parts[1].split(','),
        'timestamp': parts[2],
        'nonce': parts[3],
        'ip': parts[4],
        'signature': parts[5]
    }

def _validate_timestamp(timestamp_str: str, max_age: int = SESSION_TIMEOUT) -> bool:
    """Check if token timestamp is within acceptable range."""
    try:
        ts = int(timestamp_str)
    except (ValueError, TypeError):
        return False
    now = int(time.time())
    # Token must not be from the future and must not be expired
    if ts > now + 30:  # 30 second clock skew allowance
        return False
    if now - ts > max_age:
        return False
    return True

def _compute_expected_signature(payload_str: str) -> str:
    """Compute the expected HMAC signature for a payload."""
    return hmac.new(SECRET_KEY, payload_str.encode(), hashlib.sha256).hexdigest()

def _extract_payload_from_token(token: str) -> str:
    """Extract the payload portion (everything before the last | separator).

    The signature is always the last component after the final pipe.
    We reconstruct the payload by joining all parts except the signature.
    """
    # Find the last pipe separator - signature follows it
    last_pipe = token.rfind('|')
    if last_pipe <= 0:
        return None
    return token[:last_pipe]

def _check_nonce_reuse(nonce: str, user_id: str) -> bool:
    """Verify nonce hasn't been used before (replay protection).
    Returns True if nonce is fresh (not reused)."""
    session_key = f"{user_id}:{nonce}"
    if session_key in ACTIVE_SESSIONS:
        session = ACTIVE_SESSIONS[session_key]
        # Session exists - check if it's the same active session
        if session.get('active', False):
            return True  # Same active session, allow
        return False  # Nonce was used in expired session
    # New nonce - register it
    ACTIVE_SESSIONS[session_key] = {'active': True, 'created': time.time()}
    return True

def validate_request_token(token: str, client_ip: str) -> dict:
    """Validate an incoming request token.

    Performs:
    1. Structure validation
    2. Signature verification (timing-safe)
    3. Timestamp validation
    4. IP binding verification
    5. Nonce replay protection
    """
    if not token or not isinstance(token, str):
        return {'valid': False, 'error': 'missing_token'}

    # Length sanity check
    if len(token) > 512:
        return {'valid': False, 'error': 'token_too_long'}

    # Parse token structure
    parsed = _parse_token_parts(token)
    if parsed is None:
        return {'valid': False, 'error': 'malformed_token'}

    # Verify signature
    payload = _extract_payload_from_token(token)
    if payload is None:
        return {'valid': False, 'error': 'invalid_payload'}

    expected_sig = _compute_expected_signature(payload)
    provided_sig = parsed['signature']

    if not constant_time_compare(expected_sig.encode(), provided_sig.encode()):
        return {'valid': False, 'error': 'invalid_signature'}

    # Verify timestamp
    if not _validate_timestamp(parsed['timestamp']):
        return {'valid': False, 'error': 'expired_token'}

    # Verify IP binding
    if parsed['ip'] != client_ip:
        return {'valid': False, 'error': 'ip_mismatch'}

    # Check nonce (replay protection)
    if not _check_nonce_reuse(parsed['nonce'], parsed['user_id']):
        return {'valid': False, 'error': 'replay_detected'}

    return {
        'valid': True,
        'user_id': parsed['user_id'],
        'roles': parsed['roles'],
    }

def sanitize_path(path: str) -> str:
    """Sanitize URL path to prevent traversal."""
    # Decode URL encoding
    decoded = unquote(path)
    # Remove null bytes
    decoded = decoded.replace('\x00', '')
    # Normalize path separators
    decoded = decoded.replace('\\', '/')
    # Collapse multiple slashes
    decoded = re.sub(r'/+', '/', decoded)
    # Remove traversal attempts
    parts = decoded.split('/')
    safe_parts = []
    for part in parts:
        if part == '..':
            if safe_parts:
                safe_parts.pop()
        elif part and part != '.':
            safe_parts.append(part)
    return '/' + '/'.join(safe_parts)

def check_authorization(user_roles: list, required_role: str) -> bool:
    """Check if user has the required role."""
    if not isinstance(user_roles, list):
        return False
    if not required_role:
        return True
    return required_role in user_roles

def handle_api_request(method: str, path: str, token: str, client_ip: str, body: bytes = b'') -> dict:
    """Main API request handler with full auth pipeline."""
    # Input validation
    if not method or method.upper() not in ('GET', 'POST', 'PUT', 'DELETE'):
        return {'status': 405, 'error': 'method_not_allowed'}

    if body and len(body) > MAX_REQUEST_SIZE:
        return {'status': 413, 'error': 'payload_too_large'}

    # Path sanitization
    safe_path = sanitize_path(path)

    # Token validation
    auth_result = validate_request_token(token, client_ip)
    if not auth_result['valid']:
        return {'status': 401, 'error': auth_result['error']}

    # Route-based authorization
    if safe_path.startswith('/admin'):
        if not check_authorization(auth_result['roles'], 'admin'):
            return {'status': 403, 'error': 'insufficient_privileges'}
    elif safe_path.startswith('/internal'):
        if not check_authorization(auth_result['roles'], 'service'):
            return {'status': 403, 'error': 'insufficient_privileges'}

    return {
        'status': 200,
        'user': auth_result['user_id'],
        'path': safe_path,
        'method': method.upper()
    }

def cleanup_expired_sessions():
    """Remove expired sessions from the active sessions store."""
    now = time.time()
    expired = []
    for key, session in ACTIVE_SESSIONS.items():
        if now - session.get('created', 0) > SESSION_TIMEOUT:
            expired.append(key)
    for key in expired:
        ACTIVE_SESSIONS[key] = {'active': False, 'created': ACTIVE_SESSIONS[key]['created']}
